<script lang="ts">
 import {untrack} from 'svelte';
 import type {ToolState} from '../../types';
 import Result from '../../components/Result.svelte';
 let {state=$bindable()}=$props<{state:ToolState}>();
 import {onDestroy} from 'svelte';import {workerTask} from '../../worker-task';import Worker from './file.worker?worker';import {download} from '../../browser-files';let busy=$state(false),error=$state('');const controller=new AbortController();onDestroy(()=>controller.abort());untrack(()=>{state.files??=[];state.pages??=[];});async function select(e:Event){const files=[...((e.target as HTMLInputElement).files||[])];busy=true;error='';try{if(state.files.length+files.length>10||[...state.files,...files].reduce((n:number,f:File)=>n+f.size,0)>60*1024*1024)throw new Error('10ファイル・合計60MB以内です。');const added=[];for(const file of files){if(file.size>30*1024*1024)throw new Error('1ファイル30MB以内です。');const count=await workerTask<number>(new Worker(),{files:[file]},controller.signal);added.push({file,count});}if(state.pages.length+added.reduce((n,x)=>n+x.count,0)>300)throw new Error('合計300ページ以内です。');for(const {file,count} of added){const index=state.files.length;state.files.push(file);state.pages.push(...Array.from({length:count},(_,i)=>({file:index,index:i,rotation:0,selected:true})));}}catch(e){error=(e as Error).message;}finally{busy=false;(e.target as HTMLInputElement).value='';}}
 function move(i:number,d:number){[state.pages[i],state.pages[i+d]]=[state.pages[i+d],state.pages[i]];}
 async function save(){busy=true;error='';try{const bytes=await workerTask<Uint8Array>(new Worker(),{files:state.files,pages:state.pages.filter((p:any)=>p.selected)},controller.signal);download(new Blob([bytes as BlobPart],{type:'application/pdf'}),'organized.pdf');}catch(e){error=(e as Error).message;}finally{busy=false;}}
 
</script>
<label>PDFを追加（複数選択可）<input type="file" accept="application/pdf,.pdf" multiple disabled={busy} onchange={select}/></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<p role="status">{busy?'PDF処理中…':`${state.pages.length}ページ。チェックしたページを現在の順序で抽出・結合します。`}</p>{#each state.pages as page,i}<fieldset disabled={busy}><legend>{i+1}番目</legend><label><input type="checkbox" bind:checked={page.selected}/><span style="overflow-wrap:anywhere">{state.files[page.file].name} — 元ページ {page.index+1} / 追加回転 {page.rotation}°</span></label><div class="action-row"><button disabled={i===0} aria-label={`${i+1}番目を上へ`} onclick={()=>move(i,-1)}>上へ</button><button disabled={i===state.pages.length-1} aria-label={`${i+1}番目を下へ`} onclick={()=>move(i,1)}>下へ</button><button onclick={()=>page.rotation=(page.rotation+90)%360}>90°回転</button><button onclick={()=>state.pages.splice(i,1)}>削除</button></div></fieldset>{/each}<div class="action-row"><button class="primary" disabled={busy||!state.pages.some((p:any)=>p.selected)} onclick={save}>選択ページをPDF保存</button><button disabled={busy} onclick={()=>{state.files=[];state.pages=[];error='';}}>すべてクリア</button></div><p class="tool-note">例：PDFを2つ追加し、「下へ」で順序変更、不要ページのチェックを外して保存。1ファイル30MB・合計60MB・10ファイル・300ページ、Worker処理20秒上限。暗号化・破損PDFは非対応。ページは番号一覧（画像プレビューなし）。フォーム、注釈、しおり、署名等の文書全体の機能・有効性は保持を保証しません。元PDFは変更しません。</p>
